package backend.nemra.modules.auth.dto;import jakarta.validation.constraints.NotNull;import lombok.Data;import lombok.RequiredArgsConstructor;@Data@RequiredArgsConstructorpublic class RegisterRequest {    @NotNull(message = "full name is required")    private String fullName;    @NotNull(message = "phone number is required")    private String phoneNumber;    @NotNull(message = "password is required")    private String password;    private String city;}